DeviceProperties.ListenerScriptPacketParser:
IF (INDEXOF(RECEIVEDMSG.TOPIC,deviceId + "/ctlv3/z1RoomTemp") >= 0)
    Te := PARSEJSON(RECEIVEDMSG.PAYLOAD,"tempv.value", true);
ELSEIF (INDEXOF(RECEIVEDMSG.TOPIC,deviceId + "/ctlv3/z1HeatingRoomTempDesiredManualControlled") >= 0)
    Se := PARSEJSON(RECEIVEDMSG.PAYLOAD,"tempv.value", true);
ELSEIF (INDEXOF(RECEIVEDMSG.TOPIC,deviceId + "/ctlv3/z1RoomHumidity") >= 0)
    Hu := TODOUBLE(PARSEJSON(RECEIVEDMSG.PAYLOAD,"0.value", true));
END

IF (INDEXOF(RECEIVEDMSG.TOPIC,deviceId + "/bai/Status01") >= 0)
    Mu := SWITCH(PARSEJSON(RECEIVEDMSG.PAYLOAD,"5.value", true), "on", 1, "warm water circuit", 2, 0);
END

